//#region clis/file-system/get-config.ts
function getConfig(path = "./powerhouse.config.json") {
	let config = { ...DEFAULT_CONFIG };
	try {
		const configStr = readFileSync(path, "utf-8");
		const userConfig = JSON.parse(configStr);
		config = {
			...config,
			...userConfig
		};
	} catch {}
	return config;
}
